UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Infectologia / Antimicrobiano","pharmacological_class":"Fluoroquinolona","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"500 mg","interval_text":"12/12 horas (ou 24/24 horas para levofloxacino/moxifloxacino)","route":"Via oral / Intravenosa","duration_text":"7 a 14 dias conforme o foco infeccioso","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Antimicrobianos - 2 vias)"}],"contraindications":["Hipersensibilidade a quinolonas, histórico de tendinopatia associada a quinolonas, miastenia gravis e gestação."],"renal_adjustment":"ClCr 30–50 mL/min: dose padrão a cada 18–24h. ClCr < 30 mL/min: reduzir dose em 50% ou aumentar intervalo.","hepatic_adjustment":"Ajuste geralmente não necessário (exceto moxifloxacino em Child-Pugh C).","adverse_reactions":["Tendinite/ruptura tendínea (aquiles), prolongamento de intervalo QTc, náuseas, diarreia e neuropatia periférica."],"drug_interactions":["Antiácidos, ferro e cálcio quelam a quinolona reduzindo severamente a absorção; evitar antiarrítmicos que prolonguem QTc."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 3526;
UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Uso Clínico Geral","pharmacological_class":"Princípio Ativo Farmacêutico Padronizado","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose individualizada conforme indicação médica","interval_text":"12/12 horas (ou a cada 24 horas conforme protocolo clínico)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Hipersensibilidade grave ao princípio ativo ou aos componentes da fórmula.","Avaliar contraindicações específicas na gestação, lactação e insuficiência orgânica grave."],"renal_adjustment":"Avaliar taxa de filtração glomerular (TFG / ClCr). Ajustar dose ou intervalo em insuficiência renal moderada a grave conforme clearance.","hepatic_adjustment":"Usar com cautela em hepatopatias moderadas a graves; monitorar enzimas hepáticas periodicamente.","adverse_reactions":["Distúrbios gastrointestinais leves (náuseas, desconforto abdominal, dispepsia).","Cefaleia, tontura ou fadiga transitória.","Reações alérgicas cutâneas (erupção cutânea, prurido, urticária)."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 2794;
UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Oncologia e Hematologia / Imunologia Avançada","pharmacological_class":"Terapia-alvo / Inibidor de tirosina quinase ou anticorpo monoclonal","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose individualizada conforme indicação médica","interval_text":"12/12 horas (ou a cada 24 horas conforme protocolo clínico)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Hospitalar / Oncologia)"}],"contraindications":["Hipersensibilidade grave, gravidez e lactação, e infecções graves ativas não controladas."],"renal_adjustment":"Ajustar dose conforme toxicidade hematológica/renal e clearance de creatinina descrito em protocolo oncológico.","hepatic_adjustment":"Monitorar transaminases e bilirrubina a cada ciclo; suspender ou reduzir dose em toxicidade hepática grau ≥ 3.","adverse_reactions":["Mielossupressão (neutropenia, anemia, plaquetopenia), fadiga, diarreia, rash cutâneo e risco de infecções oportunistas."],"drug_interactions":["Substratos e inibidores potentes de CYP3A4 podem alterar drasticamente as concentrações plasmáticas."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
