UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Psiquiatria / Antidepressivo","pharmacological_class":"Inibidor Seletivo da Recaptação de Serotonina (ISRS)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose inicial terapêutica padrão com aumento gradual se necessário","interval_text":"24/24 horas (pela manhã ou à noite)","route":"Via oral","duration_text":"Tratamento de manutenção contínuo por no mínimo 6 a 12 meses","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Branca - 2 vias)"}],"contraindications":["Uso concomitante com inibidores da monoaminoxidase (IMAO) ou no intervalo de 14 dias de sua interrupção."],"renal_adjustment":"Sem necessidade de ajuste em insuficiência renal leve a moderada; cautela se TFG < 30 mL/min.","hepatic_adjustment":"Reduzir dose em 50% em pacientes com insuficiência hepática compensada.","adverse_reactions":["Náuseas, cefaleia, insônia ou sonolência, disfunção sexual (redução da libido, anorgasmia) e agitação inicial transitória."],"drug_interactions":["Risco de Síndrome Serotoninérgica com outros agentes serotoninérgicos (tramadol, triptanos, lítio)."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
