UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Anti-inflamatório Não Esteroidal (AINE) e Analgésico","pharmacological_class":"Inibidor da Ciclo-oxigenase (COX)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose anti-inflamatória padrão","interval_text":"24/24 horas","route":"Via oral","duration_text":"Menor tempo possível (3 a 5 dias para dor aguda, máx 7 dias)","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Úlcera péptica ativa, sangramento gastrointestinal ativo, insuficiência cardíaca grave, ClCr < 30 mL/min, 3º trimestre gestação."],"renal_adjustment":"Evitar em ClCr < 30 mL/min devido ao risco de lesão renal aguda e retenção hídrica.","hepatic_adjustment":"Usar com extrema cautela; contraindicado em cirrose descompensada.","adverse_reactions":["Epigastralgia, náuseas, dispepsia, retenção hidrossalina, piora da PA e risco de sangramento gastrointestinal."],"drug_interactions":["Anula o efeito cardioprotetor da aspirina, eleva níveis de lítio e metotrexato, reduz efeito de anti-hipertensivos."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
