UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Cardiologia / Anti-hipertensivo","pharmacological_class":"Antagonista do Receptor da Angiotensina II (BRA)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"50 mg a 100 mg (losartana) ou dose equivalente","interval_text":"24/24 horas (ou dividida de 12/12 horas para controle pressórico estrito)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Gravidez e lactação, estenose bilateral de artéria renal, hipersensibilidade aos componentes."],"renal_adjustment":"Não necessita de ajuste inicial, mas exige monitoramento de ureia, creatinina e potássio se TFG < 30 mL/min.","hepatic_adjustment":"Iniciar com doses mais baixas em hepatopatia leve a moderada devido à eliminação biliar.","adverse_reactions":["Hipotensão, tontura, hipercalemia e astenia transitória."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
