UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Cardiologia e Metabolismo / Hipolipemiante","pharmacological_class":"Inibidor da HMG-CoA Redutase (Estatina)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"10 mg a 40 mg","interval_text":"24/24 horas (administrado à noite ou em horário fixo)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Doença hepática ativa, elevações persistentes e inexplicadas das transaminases, gestação e lactação."],"renal_adjustment":"Atorvastatina dispensam ajuste renal; rosuvastatina e sinvastatina requerem dose inicial menor se ClCr < 30 mL/min.","hepatic_adjustment":"Contraindicado em hepatopatia ativa ou elevação de ALT/AST > 3x o limite superior da normalidade.","adverse_reactions":["Mialgia, miosite, elevação de transaminases, cefaleia e raramente rabdomiólise."],"drug_interactions":["Evitar inibidores potentes de CYP3A4 com sinvastatina (risco multiplicado de rabdomiólise)."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
