SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Infectologia / Antimicrobiano","pharmacological_class":"Macrolídeo","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"500 mg","interval_text":"24/24 horas (azitromicina) ou 12/12 horas (claritromicina)","route":"Via oral","duration_text":"3 a 5 dias (azitromicina) ou 7 a 14 dias (claritromicina)","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Antimicrobianos - 2 vias)"}],"contraindications":["Hipersensibilidade a macrolídeos, histórico de icterícia colestática associada, e uso com derivados do ergot."],"renal_adjustment":"Azitromicina: sem ajuste se ClCr > 10 mL/min. Claritromicina: reduzir dose em 50% se ClCr < 30 mL/min.","hepatic_adjustment":"Usar com precaução em insuficiência hepática moderada a grave.","adverse_reactions":["Distúrbios gastrointestinais (dor abdominal, cólicas, náuseas), diarreia, cefaleia e risco de prolongamento QTc."],"drug_interactions":["Claritromicina é potente inibidor de CYP3A4, aumentando níveis de estatinas, varfarina e carbamazepina."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 4495;
UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Ginecologia e Endocrinologia / Terapia Hormonal","pharmacological_class":"Hormônio sexual esteroide / Anticoncepcional","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose individualizada conforme indicação médica","interval_text":"12/12 horas (ou a cada 24 horas conforme protocolo clínico)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Histórico ou presença de tromboembolismo venoso ou arterial ativo.","Neoplasia maligna hormônio-dependente conhecida ou suspeita (ex.: câncer de mama ou endométrio).","Doença hepática aguda grave ou tumores hepáticos."],"renal_adjustment":"Avaliar taxa de filtração glomerular (TFG / ClCr). Ajustar dose ou intervalo em insuficiência renal moderada a grave conforme clearance.","hepatic_adjustment":"Contraindicado em insuficiência hepática descompensada ou tumores hepáticos.","adverse_reactions":["Mastalgia, sangramento uterino irregular, náuseas, cefaleia e risco aumentado de tromboembolismo venoso."],"drug_interactions":["Indutores enzimáticos (rifampicina, carbamazepina, fenitoína) reduzem a eficácia contraceptiva."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
